INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Two investigations — a federal agent working ritual killings and a writer escaping a manuscript that is authoring reality — are legible within minutes and immediately imply each other.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'story_hook' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Saga Anderson is a rare thing in horror: a competent professional with a life outside the plot. Wake''s self-loathing writerly vanity gives the second half a genuinely different voice rather than a second protagonist skin.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'character_investment' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'The internal rules of the Dark Place are applied consistently, but the game deliberately withholds resolution and ends on an unclosed loop. Coherent at the level it requires, not at the level a viewer wanting closure would want.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_coherence' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Each chapter reframes what the previous one meant, and the two storylines converge rather than merely alternate. Setup and payoff stay proportionate across a long runtime.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_momentum' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Manuscript pages, TV segments, radio and cross-title continuity all feed the central mystery instead of sitting beside it as optional collectible fiction.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'world_lore_integration' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Scene construction and performance are exceptional for the medium, and the register shifts — procedural, pulp, musical, comic — are controlled rather than indulgent.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'dramatic_execution' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Shooting is readable and weighty but intentionally sluggish; enemy tracking and the dodge can feel imprecise in crowded encounters. Implementation is competent, not a strength.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'gameplay_execution' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'It shipped in an unusually clean state for its ambition: no significant bug or crash reporting, and stable performance on console. PC is demanding at ray-traced presets, but hardware cost is not the same thing as instability, and the subcriterion measures the latter.', 'PS5 / Xbox Series X|S: stable. PC: heavy GPU demand at RT/path-traced settings, so the experience varies by hardware.' FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'technical_stability' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Art, sound, live action, UI and lighting are unusually unified; the Mind Place and the Writer''s Room feel authored by the same hand as the world outside them.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'production_cohesion' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Quality holds across a long runtime, but the combat encounters in the later Dark Place chapters lean on repetition the rest of the game avoids.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'consistency' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'The player-chosen order of the two campaigns is a structural argument, not a convenience: which story you advance changes what the other half means when you return to it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'structural_intentionality' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Hub areas are hand-authored and readable, with clear landmarks. The Dark Place intentionally disorients, and a few late routes are harder to parse than the design needs them to be.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'navigation_legibility' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Areas are revisited with meaningful transformation rather than re-run, though the Taken encounters themselves recycle a small set of patterns.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'repetition_control' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'The Mind Place and Plot Board are inspired but add navigation steps to routine actions; inventory management is functional but fiddly under pressure.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'ux_friction' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'There is essentially no filler. Optional content — nursery rhymes, cult stashes, coffee thermoses — is short, thematically placed and never gates the campaign.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'content_focus' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Light-then-shoot combat gives input real consequence, but the character''s mobility is deliberately constrained and the margin for reaction is narrow.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'moment_to_moment' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'A small arsenal plus flares, flashbangs and the flashlight covers the encounter design, but there is little room for expression or personal approach.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'toolset_depth' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'The strongest rewards are narrative and investigative — a case-board connection resolving — rather than mechanical. Weapon upgrades are modest and slow.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'reward_rhythm' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Checkpointing is generous and death costs little, though ambushes in tight geometry can feel arbitrary rather than readable.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'failure_fairness' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Resource scarcity is calibrated so the player is pressured but never helpless. The game is a survival horror that lets you fight, not one that removes the option.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'capability_balance' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
