INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Nothing here is padding. Every biome, weapon, parasite and artefact exists to feed the same loop, and the game contains no side content added to inflate its length.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'content_focus' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
