INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Resistance is exemplary here: bullet patterns are readable, damage is nearly always avoidable, and a death is almost always traceable to a specific mistake. The time a death costs is real, but that is a question of time respect, and it is scored there rather than twice.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'failure_fairness' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
