INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 2, 'Act 3 and the second ending do not merely add information — they retroactively change what every previous run was, turning a survival story into something considerably worse and sadder.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'player_recontextualization' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
