INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'A vampire-besieged island town is a serviceable premise, but the game states it rather than dramatising it, and the stakes never sharpen past the opening.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'story_hook' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'The four heroes have distinct silhouettes and abilities but almost no arc; they comment on events rather than being changed by them.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'character_investment' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'The plot holds together at a basic level, though the relationship between the cult, the vampire gods and the town''s collapse stays underspecified.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_coherence' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 0.5, 'Story is delivered mostly through static mission briefings and text; long stretches pass with no development, and the finale arrives without adequate build.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_momentum' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'Environmental storytelling in the abandoned houses is the strongest narrative material in the game, but it sits beside the plot rather than feeding it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'world_lore_integration' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'Voice work is competent and occasional lines land, but scene construction is minimal and most exposition is delivered standing still in a safe house.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'dramatic_execution' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1.5, 'Gunplay itself is reasonable and the ability sets are readable. Enemy AI, pathing and reaction behaviour are the clearest implementation weakness.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'gameplay_execution' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'The final build includes the 60fps Performance Mode introduced in Update 2; Update 4 added offline play and pausing, but pop-in, traversal hitching and animation faults remain routine.', 'Assessed on Xbox Series X|S and PC at the Game Update 4 build.' FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'technical_stability' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'Art direction and systems design point in different directions: the town is dressed as an immersive sim while the mission and loot layer is a live-service shooter.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'production_cohesion' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'Quality is uniformly mid rather than uneven — the second district repeats the structure of the first without improving on it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'consistency' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1), s.id, 1, 'The open-world-plus-safehouse form is a recognisable shape, but it serves neither the co-op shooter nor the immersive-sim instincts the game keeps gesturing at.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'structural_intentionality' AND EXISTS (SELECT 1 FROM _seed_new_evaluations seeded WHERE seeded.evaluation_id = (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.rubric_version = '1.0' AND e.version_number = 1)) ON CONFLICT DO NOTHING;
